R = Registry()
SRC: dict[str, dict] = {}

BAND_TEXT = [
    'little understanding of the demands of the question; poorly structured, little relevant knowledge, no analysis',
    'some indication of the demands; some knowledge but lacking accuracy or relevance; mostly narrative or descriptive, limited analysis',
    'demands understood but not all implications considered; mostly accurate knowledge; some critical analysis, though partly narrative',
    'clear awareness of the demands; clearly structured; accurate, relevant knowledge placed in context; analysis with most points substantiated; some awareness of different perspectives',
    'clearly focused, well structured response; accurate and relevant knowledge used effectively; well-chosen examples; evaluation of different perspectives; all main points substantiated; reasoned, consistent conclusion',
]
SYNTH_TEXT = [
    'limited understanding; generalised comments, sources or own knowledge used descriptively',
    'some focus on the question; uses sources or own knowledge, with some analysis but little synthesis',
    'focused response; effective use of the sources and accurate own knowledge, integrated (synthesised) to support a clear, balanced judgement',
]

STYLE = {
    'essay_marks': 15, 'eval_marks': 10,
    'markband': ('Use the IB Paper 2/3 markbands, scaled to the marks: top band – clearly focused, well structured, '
                 'accurate and relevant knowledge used to support critical analysis, different perspectives evaluated, '
                 'reasoned conclusion; middle band – mostly accurate knowledge, some analysis but partly narrative; '
                 'lower band – little understanding of the demands, mainly description.'),
}


def bands(m: int, texts) -> str:
    n = len(texts)
    edges = [round(m * i / n) for i in range(n + 1)]
    out = ['0: does not reach the standard of the descriptors below']
    for i in range(n):
        lo, hi = edges[i] + 1, edges[i + 1]
        if lo > hi:
            continue
        out.append(f'{lo}–{hi}: {texts[i]}' if lo != hi else f'{hi}: {texts[i]}')
    return 'Markbands – ' + '; '.join(reversed(out)) + '.'


def lc(s: str) -> str:
    return s[0].lower() + s[1:] if s.split(' ')[0] in LOWERABLE else s


LOWERABLE = {'The', 'A', 'An', 'It', 'In', 'Its', 'Their', 'There', 'This', 'Without', 'International', 'Economic',
             'Propaganda', 'Terror', 'Ideology', 'Social', 'Foreign', 'Colonial', 'Charismatic', 'Western', 'Historians',
             'Historical', 'Primary', 'Sources', 'Gacaca', 'Justice', 'Media', 'Control', 'Military', 'Most', 'Only',
             'Comparing', 'Using', 'Change', 'Causation', 'Continuity', 'Significance', 'Perspectives', 'Every', 'All',
             'Long', 'Short', 'Visual', 'Official', 'Contemporary', 'Memory', 'Commemoration', 'Women', 'Youth',
             'Education', 'Opposition', 'Legal', 'Force', 'Mass', 'National', 'Ethnic', 'Revisionist', 'Marxist',
             'Structuralist', 'Intentionalist', 'Choosing', 'Referencing', 'Academic', 'Reflection', 'Planning',
             'Thesis', 'Counter', 'Command', 'Evidence', 'Writing', 'Humanitarian', 'Failure', 'Weak', 'Personal'}


LETTERS = 'ABC'


def _src_block(label, s):
    return f'Source {label}: {s[1]}\n\n{s[0]}'


def source_templates(key: str, d: dict) -> list:
    src, topic, cmp_, ev, essays = d['src'], d['topic'], d['cmp'], d['ev'], d['essays']
    out = []

    def message(rng, slot):
        i = rng.randrange(len(src))
        s = src[i]
        lab = rng.choice(LETTERS)
        m = slot.marks or (2 if slot.d <= 2 else 3)
        q = rng.choice([
            f'What is the message of Source {lab} about {topic}?',
            f'Identify the main points that Source {lab} makes about {topic}, using details from the source.',
            f'What does Source {lab} suggest about {topic}? Refer closely to the source in your answer.',
            f'Explain the view of {topic} that is presented in Source {lab}.',
            f'Summarise the argument conveyed by Source {lab} in relation to {topic}.',
        ])
        return dict(stem=_src_block(lab, s) + '\n\n' + q, answer=s[2], type='case', marks=m, minutes=float(3 * m),
                    markingKey=f'{s[2]} Award 1 mark for each relevant point drawn from the source, up to [{m}]. '
                               'Points must come from the source itself; own knowledge is not credited in this question.', gap='G7')
    out.append(T('C3', (2, 4), message, 'case', 'p1_message', 'p1_message'))

    def opvl(rng, slot):
        i = rng.randrange(len(src))
        s = src[i]
        lab = rng.choice(LETTERS)
        m = slot.marks or (3 if slot.d <= 3 else 4)
        q = rng.choice([
            f'With reference to its origin, purpose and content, analyse the value and limitations of Source {lab} for an historian studying {topic}.',
            f'Assess the usefulness of Source {lab} to an historian investigating {topic}, referring to who produced it, when, why and what it contains.',
            f'An historian is researching {topic}. Explain the value and limitations of Source {lab} for this research, with reference to its origin, purpose and content.',
            f'How far can Source {lab} be trusted as evidence for {topic}? Refer to the origin, purpose and content of the source.',
            f'Evaluate Source {lab} as evidence about {topic}, considering its author, date, intended audience and content.',
        ])
        return dict(stem=_src_block(lab, s) + '\n\n' + q, answer=f'Value: {s[3]} Limitations: {s[4]}', type='case', marks=m,
                    minutes=float(3 * m),
                    markingKey=f'Value: {s[3]} Limitations: {s[4]} Award up to [{m}]: the response must refer to origin, purpose and content '
                               'and link each to value or limitation for the stated enquiry; at least one value and one limitation are needed for full marks; '
                               'a list of features without explaining their effect on value is capped at half marks.', gap='G7')
    out.append(T(('C3', 'C4'), (2, 5), opvl, 'case', 'p1_opvl', 'p1_opvl'))

    if len(src) >= 2 and cmp_:
        def compare(rng, slot):
            # cmp texts refer to the first source as A and the second as B, so keep the order fixed
            a, b = 0, 1
            la, lb = 'A', 'B'
            m = slot.marks or (4 if slot.d <= 3 else 6)
            q = rng.choice([
                f'Compare and contrast what Sources {la} and {lb} reveal about {topic}.',
                f'Compare and contrast the views expressed in Source {la} and Source {lb} on {topic}.',
                f'In what ways do Sources {la} and {lb} agree and disagree about {topic}?',
                f'To what extent do Sources {la} and {lb} present a similar picture of {topic}?',
            ])
            first, second = (src[a], src[b])
            return dict(stem=_src_block(la, first) + '\n\n' + _src_block(lb, second) + '\n\n' + q,
                        answer=cmp_, type='case', marks=m, minutes=float(3 * m),
                        markingKey=f'{cmp_} Award 1 mark per valid, explicitly linked point of comparison or contrast, up to [{m}]; '
                                   'at least one comparison and one contrast are needed for full marks. A running (integrated) comparison is '
                                   'preferred to end-on description; do not credit points about provenance in this question.', gap='G7')
        out.append(T('C4', (3, 5), compare, 'case', 'p1_compare', 'p1_compare'))

    if len(src) >= 2 and ev:
        def synth(rng, slot):
            claim, pro, con, judge = rng.choice(ev)
            m = slot.marks or (8 if slot.d <= 4 else 9)
            q = rng.choice([
                f'Using the sources and your own knowledge, to what extent do you agree that {lc(claim).rstrip(".")}?',
                f'Using the sources and your own knowledge, evaluate the claim that {lc(claim)}',
                f'Using the sources and your own knowledge, discuss the view that {lc(claim)}',
                f'“{claim}” Using Sources A and B and your own knowledge, how far do you agree with this statement?',
                f'With reference to both sources and your own knowledge, assess the validity of the argument that {lc(claim)}',
            ])
            s1, s2 = (src[0], src[1]) if rng.random() < 0.5 else (src[1], src[0])
            stem = _src_block('A', s1) + '\n\n' + _src_block('B', s2) + '\n\n' + q
            key = ('Indicative content – supporting: ' + '; '.join(pro) + '. Challenging: ' + '; '.join(con) +
                   f'. Judgement: {judge} Candidates must use both sources and their own knowledge; ' + bands(m, SYNTH_TEXT))
            return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=m, minutes=float(3 * m), gap='G5')
        out.append(T('C4', (3, 5), synth, 'long', 'p1_synth', 'p1_synth'))

    if ev or essays:
        def essay(rng, slot):
            m = slot.marks or 15
            pool = [('E', e) for e in essays] + [('V', e) for e in ev]
            kind, e = rng.choice(pool)
            if kind == 'E':
                stem, pts, judge = e
                pro, con = pts, []
            else:
                claim, pro, con, judge = e
                stem = rng.choice([
                    f'"{claim}" With reference to specific historical evidence, discuss the validity of this view.',
                    f'Evaluate the strengths and weaknesses of the argument that {lc(claim)}',
                ])
            key = 'Indicative content: ' + '; '.join(list(pro) + list(con)) + f'. A strong answer reaches a judgement such as: {judge} ' + bands(m, BAND_TEXT)
            return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=m, minutes=float(min(60, 3.5 * m)), gap='G5')
        out.append(T('C4', (3, 5), essay, 'long', 'essay', 'essay'))
    return out


LOWER_OK = {'The', 'A', 'An', 'It', 'In', 'Its', 'There', 'This', 'Any', 'All', 'Only', 'Long-term', 'After', 'Comparison',
            'Structuralist', 'Revisionist', 'Fascism', 'Primary', 'Propaganda', 'Economic', 'Terror', 'Ideology', 'Foreign',
            'Strategic', 'Situational', 'Official', 'Historians', 'Academic', 'Comparing', 'Continuity', 'Causation',
            'Perspectives', 'If', 'Every', 'Racism', 'Memorials', 'Commemoration', 'Quoting', 'Paraphrasing', 'Using',
            'Websites', 'Gacaca', 'Significance', 'Authoritarian', 'Propaganda', 'Recency'}
FIXES: list = []   # (wrongly lower-cased claim start, correct form) – the shared frames lower-case the first letter


def _note_fix(claim):
    if claim.split(' ')[0] not in LOWER_OK:
        good = claim.rstrip('.')
        FIXES.append((good[0].lower() + good[1:], good))


def _wrap(t):
    fn = t.fn

    def fixed(rng, slot):
        out = fn(rng, slot)
        if out:
            for bad, good in FIXES:
                if bad in out['stem']:
                    out['stem'] = out['stem'].replace(bad, good)
        return out
    t.fn = fixed
    return t


def H(key, topic, terms=(), facts=(), why=(), contrast=(), misc=(), cases=(), src=(), cmp='', ev=(), essays=(),
      apply=(), extended=()):
    terms = [(t.replace('“', '').replace('”', ''), d) for t, d in terms]
    for e in list(ev) + list(misc):
        _note_fix(e[0])
    R.facts(key, F(terms=list(terms), facts=list(facts), why=list(why), contrast=list(contrast), misc=list(misc),
                   apply=list(apply), cases=list(cases), evaluate=list(ev), extended=list(extended)))
    SRC[key] = dict(topic=topic, src=list(src), cmp=cmp, ev=list(ev), essays=list(essays))


def init(subject_id):
    pass


def templates(st):
    key = st['id'].rsplit('-', 2)[-2] + '-' + st['id'].rsplit('-', 1)[-1]
    out = [_wrap(t) for t in R.build(st, STYLE)]
    if key in SRC:
        out += source_templates(key, SRC[key])
    return out


